    /* Gred[RC_b,P] = Grr[RC_b,P] - Grk[RC_b,k] * W * Gkr[k,P]. */
    varG_RC_b_P = codeG_RC_b_P;
    /* codeG_RC_b_N represents Gred[RC_b,N]: -Grk_shared_4*W_2_2*Gkr_k2_N. */
    codeG_RC_b_N = -Grk_shared_4*W_2_2*Gkr_k2_N;
    /* Gred[RC_b,N] = Grr[RC_b,N] - Grk[RC_b,k] * W * Gkr[k,N]. */
    varG_RC_b_N = codeG_RC_b_N;
    /* codeG_RC_c_RC_c represents Gred[RC_c,RC_c]: Grr_shared_3 - Grk_shared_4*W_3_3*Gkr_shared_4. */
    codeG_RC_c_RC_c = Grr_shared_3 - Grk_shared_4*W_3_3*Gkr_shared_4;
    /* Gred[RC_c,RC_c] = Grr[RC_c,RC_c] - Grk[RC_c,k] * W * Gkr[k,RC_c]. */
    varG_RC_c_RC_c = codeG_RC_c_RC_c;
    /* codeG_RC_c_P represents Gred[RC_c,P]: -Grk_shared_4*W_3_3*Gkr_k3_P. */
    codeG_RC_c_P = -Grk_shared_4*W_3_3*Gkr_k3_P;
    /* Gred[RC_c,P] = Grr[RC_c,P] - Grk[RC_c,k] * W * Gkr[k,P]. */
    varG_RC_c_P = codeG_RC_c_P;
    /* codeG_RC_c_N represents Gred[RC_c,N]: -Grk_shared_4*W_3_3*Gkr_k3_N. */
    codeG_RC_c_N = -Grk_shared_4*W_3_3*Gkr_k3_N;
    /* Gred[RC_c,N] = Grr[RC_c,N] - Grk[RC_c,k] * W * Gkr[k,N]. */
    varG_RC_c_N = codeG_RC_c_N;
    /* codeG_P_P represents Gred[P,P]: Grr_P_P - Grk_P_k1*W_1_1*Gkr_k1_P - Grk_P_k2*W_2_2*Gkr_k2_P - Grk_P_k3*W_3_3*Gkr_k3_P. */
    codeG_P_P = Grr_P_P - Grk_P_k1*W_1_1*Gkr_k1_P - Grk_P_k2*W_2_2*Gkr_k2_P - Grk_P_k3*W_3_3*Gkr_k3_P;
    /* Gred[P,P] = Grr[P,P] - Grk[P,k] * W * Gkr[k,P]. */
    varG_P_P = codeG_P_P;
    /* codeG_P_N represents Gred[P,N]: Grr_shared_4 - Grk_P_k1*W_1_1*Gkr_k1_N - Grk_P_k2*W_2_2*Gkr_k2_N - Grk_P_k3*W_3_3*Gkr_k3_N. */
    codeG_P_N = Grr_shared_4 - Grk_P_k1*W_1_1*Gkr_k1_N - Grk_P_k2*W_2_2*Gkr_k2_N - Grk_P_k3*W_3_3*Gkr_k3_N;
    /* Gred[P,N] = Grr[P,N] - Grk[P,k] * W * Gkr[k,N]. */
    varG_P_N = codeG_P_N;
    /* codeG_N_N represents Gred[N,N]: Grr_N_N - Grk_N_k1*W_1_1*Gkr_k1_N - Grk_N_k2*W_2_2*Gkr_k2_N - Grk_N_k3*W_3_3*Gkr_k3_N. */
    codeG_N_N = Grr_N_N - Grk_N_k1*W_1_1*Gkr_k1_N - Grk_N_k2*W_2_2*Gkr_k2_N - Grk_N_k3*W_3_3*Gkr_k3_N;
    /* Gred[N,N] = Grr[N,N] - Grk[N,k] * W * Gkr[k,N]. */
    varG_N_N = codeG_N_N;

    /* Ihisred is a per-step injection vector: Ihisred = Ihisr - Grk * W * Ihisk. */
    matrix_matXvec_CODE(&tmp_Grk_W_Ihisk_code, &tmp_Grk_W_code, &Ihisk_code);
    matrix_subtract_CODE(&Ihisred_code, &Ihisr_code, &tmp_Grk_W_Ihisk_code);
    set_CODE(&Ihisred_code, 7, 0, get_CODE(&Ihisred_code, 7, 0) + IC_his0);
    set_CODE(&Ihisred_code, 8, 0, get_CODE(&Ihisred_code, 8, 0) + -IC_his0);
    /* Node injection currents follow the retained-node order of the reduced system. */
    InjA = get_CODE(&Ihisred_code, 0, 0);
    InjB = get_CODE(&Ihisred_code, 1, 0);
    InjC = get_CODE(&Ihisred_code, 2, 0);
    InjG = get_CODE(&Ihisred_code, 3, 0);
    InjRC_a = get_CODE(&Ihisred_code, 4, 0);
    InjRC_b = get_CODE(&Ihisred_code, 5, 0);
    InjRC_c = get_CODE(&Ihisred_code, 6, 0);
    InjP = get_CODE(&Ihisred_code, 7, 0);
    InjN = get_CODE(&Ihisred_code, 8, 0);

T1_T2:
    /* Internal-node voltage recovery after solved retained-node voltages are available. */
    set_CODE(&Vr_code, 0, 0, A);
    set_CODE(&Vr_code, 1, 0, B);
    set_CODE(&Vr_code, 2, 0, C);
    set_CODE(&Vr_code, 3, 0, G);
    set_CODE(&Vr_code, 4, 0, RC_a);
    set_CODE(&Vr_code, 5, 0, RC_b);
    set_CODE(&Vr_code, 6, 0, RC_c);
    set_CODE(&Vr_code, 7, 0, P);
    set_CODE(&Vr_code, 8, 0, N);
    matrix_mult_CODE(&tmp_W_Gkr_code, &W_code, &Gkr_code);
    matrix_matXvec_CODE(&tmp_W_Gkr_Vr_code, &tmp_W_Gkr_code, &Vr_code);
    matrix_matXvec_CODE(&tmp_W_Ihisk_code, &W_code, &Ihisk_code);
    matrix_add_CODE(&tmp_Vk_sum_code, &tmp_W_Gkr_Vr_code, &tmp_W_Ihisk_code);
    matrix_scalarMult_CODE(&Vk_code, &tmp_Vk_sum_code, -1.0);

    /* One variable per eliminated node, in effective k order. */
    x = get_CODE(&Vk_code, 0, 0);
    y = get_CODE(&Vk_code, 1, 0);
    z = get_CODE(&Vk_code, 2, 0);
